PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE portfolios(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE properties(id TEXT PRIMARY KEY,portfolio_id TEXT REFERENCES portfolios(id),name TEXT NOT NULL,category TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',land_area TEXT,building_area TEXT,acquired_on TEXT,construction_date TEXT,purchase_price INTEGER NOT NULL DEFAULT 0 CHECK(purchase_price>=0),registration_cost INTEGER NOT NULL DEFAULT 0 CHECK(registration_cost>=0),ownership_bps INTEGER NOT NULL DEFAULT 10000 CHECK(ownership_bps BETWEEN 1 AND 10000),insurance TEXT,utilities TEXT,notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE buildings(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES properties(id),name TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(property_id,name));
CREATE TABLE floors(id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id),name TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(building_id,name));
CREATE TABLE owners(id TEXT PRIMARY KEY,name TEXT NOT NULL,contact TEXT,created_at TEXT NOT NULL);
CREATE TABLE ownership_shares(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES properties(id),owner_id TEXT NOT NULL REFERENCES owners(id),basis_points INTEGER NOT NULL CHECK(basis_points BETWEEN 1 AND 10000),effective_on TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE units(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES properties(id),building_id TEXT REFERENCES buildings(id),floor_id TEXT REFERENCES floors(id),number TEXT NOT NULL,type TEXT NOT NULL,size TEXT,bedrooms INTEGER,bathrooms INTEGER,monthly_rent INTEGER NOT NULL CHECK(monthly_rent>=0),service_charge INTEGER NOT NULL DEFAULT 0 CHECK(service_charge>=0),deposit_required INTEGER NOT NULL DEFAULT 0 CHECK(deposit_required>=0),status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','maintenance','retired')),notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(property_id,number));
CREATE TABLE tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,address TEXT,emergency_contact TEXT,identification_reference TEXT,occupation TEXT,guarantor TEXT,notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE leases(id TEXT PRIMARY KEY,unit_id TEXT NOT NULL REFERENCES units(id),tenant_id TEXT NOT NULL REFERENCES tenants(id),start_date TEXT NOT NULL,end_date TEXT NOT NULL CHECK(end_date>=start_date),rent INTEGER NOT NULL CHECK(rent>=0),service_charge INTEGER NOT NULL DEFAULT 0 CHECK(service_charge>=0),billing_day INTEGER NOT NULL DEFAULT 1 CHECK(billing_day BETWEEN 1 AND 28),due_day INTEGER NOT NULL DEFAULT 10 CHECK(due_day BETWEEN 1 AND 28),deposit INTEGER NOT NULL DEFAULT 0 CHECK(deposit>=0),prorate INTEGER NOT NULL DEFAULT 1 CHECK(prorate IN (0,1)),late_fee INTEGER NOT NULL DEFAULT 0 CHECK(late_fee>=0),grace_days INTEGER NOT NULL DEFAULT 0 CHECK(grace_days BETWEEN 0 AND 90),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','ended')),renewed_from TEXT REFERENCES leases(id),termination_terms TEXT,move_out_date TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TRIGGER lease_no_overlap BEFORE INSERT ON leases WHEN EXISTS(SELECT 1 FROM leases WHERE unit_id=NEW.unit_id AND NEW.start_date<=COALESCE(move_out_date,end_date) AND NEW.end_date>=start_date) BEGIN SELECT RAISE(ABORT,'Lease dates overlap an existing lease'); END;
CREATE TABLE lease_rent_schedules(id TEXT PRIMARY KEY,lease_id TEXT NOT NULL REFERENCES leases(id),effective_on TEXT NOT NULL,rent INTEGER NOT NULL CHECK(rent>=0),created_at TEXT NOT NULL,UNIQUE(lease_id,effective_on));
CREATE TABLE utility_meters(id TEXT PRIMARY KEY,unit_id TEXT NOT NULL REFERENCES units(id),name TEXT NOT NULL,rate INTEGER NOT NULL CHECK(rate>=0),created_at TEXT NOT NULL);
CREATE TABLE meter_readings(id TEXT PRIMARY KEY,meter_id TEXT NOT NULL REFERENCES utility_meters(id),month TEXT NOT NULL,previous_reading INTEGER NOT NULL CHECK(previous_reading>=0),current_reading INTEGER NOT NULL CHECK(current_reading>=previous_reading),created_at TEXT NOT NULL,UNIQUE(meter_id,month));
CREATE TABLE financial_accounts(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN('asset','liability','equity','income','expense')),cash INTEGER NOT NULL DEFAULT 0 CHECK(cash IN(0,1)),created_at TEXT NOT NULL);
CREATE TABLE journal_entries(id TEXT PRIMARY KEY,event_type TEXT NOT NULL,event_id TEXT NOT NULL,entry_date TEXT NOT NULL,description TEXT NOT NULL,property_id TEXT REFERENCES properties(id),unit_id TEXT REFERENCES units(id),tenant_id TEXT REFERENCES tenants(id),reverses_id TEXT REFERENCES journal_entries(id),created_at TEXT NOT NULL,UNIQUE(event_type,event_id),UNIQUE(reverses_id));
CREATE TABLE journal_lines(id TEXT PRIMARY KEY,entry_id TEXT NOT NULL REFERENCES journal_entries(id),account_id TEXT NOT NULL REFERENCES financial_accounts(id),debit INTEGER NOT NULL DEFAULT 0 CHECK(debit>=0),credit INTEGER NOT NULL DEFAULT 0 CHECK(credit>=0),CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE TABLE invoices(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,lease_id TEXT NOT NULL REFERENCES leases(id),month TEXT NOT NULL,issue_date TEXT NOT NULL,due_date TEXT NOT NULL,total INTEGER NOT NULL CHECK(total>=0),snapshot TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'rent' CHECK(kind IN('rent','late_fee','custom')),journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL);
CREATE TABLE invoice_items(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES invoices(id),description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),account_id TEXT NOT NULL REFERENCES financial_accounts(id));
CREATE TABLE payments(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,receipt_number TEXT NOT NULL UNIQUE,snapshot TEXT NOT NULL,lease_id TEXT NOT NULL REFERENCES leases(id),payment_date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),method TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES financial_accounts(id),reference TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL);
CREATE TABLE payment_allocations(id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES payments(id),invoice_id TEXT NOT NULL REFERENCES invoices(id),amount INTEGER NOT NULL CHECK(amount>0),created_at TEXT NOT NULL);
CREATE TABLE reversals(id TEXT PRIMARY KEY,event_type TEXT NOT NULL,event_id TEXT NOT NULL,reason TEXT NOT NULL,reversal_date TEXT NOT NULL,journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL,UNIQUE(event_type,event_id));
CREATE TABLE credit_notes(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,invoice_id TEXT NOT NULL REFERENCES invoices(id),amount INTEGER NOT NULL CHECK(amount>0),reason TEXT NOT NULL,entry_date TEXT NOT NULL,journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL);
CREATE TABLE refunds(id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES payments(id),amount INTEGER NOT NULL CHECK(amount>0),entry_date TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES financial_accounts(id),reason TEXT NOT NULL,journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL);
CREATE TABLE security_deposits(id TEXT PRIMARY KEY,lease_id TEXT NOT NULL REFERENCES leases(id),entry_date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),direction TEXT NOT NULL CHECK(direction IN('received','refunded')),account_id TEXT NOT NULL REFERENCES financial_accounts(id),reference TEXT,journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL);
CREATE TABLE vendors(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT,notes TEXT,created_at TEXT NOT NULL);
CREATE TABLE expense_categories(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);
CREATE TABLE expenses(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES properties(id),unit_id TEXT REFERENCES units(id),vendor_id TEXT REFERENCES vendors(id),category TEXT NOT NULL,description TEXT NOT NULL,entry_date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),capital INTEGER NOT NULL DEFAULT 0 CHECK(capital IN(0,1)),account_id TEXT REFERENCES financial_accounts(id),journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL);
CREATE TABLE expense_payments(id TEXT PRIMARY KEY,expense_id TEXT NOT NULL REFERENCES expenses(id),entry_date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),account_id TEXT NOT NULL REFERENCES financial_accounts(id),journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL);
CREATE TABLE maintenance_requests(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES properties(id),unit_id TEXT REFERENCES units(id),vendor_id TEXT REFERENCES vendors(id),category TEXT NOT NULL,priority TEXT NOT NULL CHECK(priority IN('low','normal','high','urgent')),description TEXT NOT NULL,reported_on TEXT NOT NULL,scheduled_on TEXT,completed_on TEXT,estimated_cost INTEGER NOT NULL DEFAULT 0 CHECK(estimated_cost>=0),status TEXT NOT NULL CHECK(status IN('open','scheduled','in_progress','completed','cancelled')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE maintenance_events(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES maintenance_requests(id),status TEXT NOT NULL,notes TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE investments(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES properties(id),entry_date TEXT NOT NULL,category TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),description TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES financial_accounts(id),journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL);
CREATE TABLE property_valuations(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES properties(id),valuation_date TEXT NOT NULL,value INTEGER NOT NULL CHECK(value>=0),notes TEXT,created_at TEXT NOT NULL);
CREATE TABLE loans(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES properties(id),lender TEXT NOT NULL,principal INTEGER NOT NULL CHECK(principal>0),annual_rate_bps INTEGER NOT NULL CHECK(annual_rate_bps BETWEEN 0 AND 10000),term_months INTEGER NOT NULL CHECK(term_months BETWEEN 1 AND 600),start_date TEXT NOT NULL,due_day INTEGER NOT NULL DEFAULT 10 CHECK(due_day BETWEEN 1 AND 28),account_id TEXT NOT NULL REFERENCES financial_accounts(id),journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL);
CREATE TABLE loan_transactions(id TEXT PRIMARY KEY,loan_id TEXT NOT NULL REFERENCES loans(id),entry_date TEXT NOT NULL,principal INTEGER NOT NULL CHECK(principal>=0),interest INTEGER NOT NULL CHECK(interest>=0),account_id TEXT NOT NULL REFERENCES financial_accounts(id),journal_id TEXT NOT NULL REFERENCES journal_entries(id),created_at TEXT NOT NULL,CHECK(principal+interest>0));
CREATE TABLE documents(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,category TEXT NOT NULL,size INTEGER NOT NULL CHECK(size>=0),content BLOB NOT NULL,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),supersedes_id TEXT REFERENCES documents(id),created_at TEXT NOT NULL);
CREATE TABLE roles(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,permissions TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,role_id TEXT NOT NULL REFERENCES roles(id),created_at TEXT NOT NULL);
CREATE TABLE activity_logs(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,details TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE backups(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,revision INTEGER NOT NULL,checksum TEXT NOT NULL,verified INTEGER NOT NULL CHECK(verified IN(0,1)));
CREATE TABLE scheduled_jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,entity_id TEXT NOT NULL,period TEXT NOT NULL,status TEXT NOT NULL,ran_at TEXT NOT NULL,UNIQUE(kind,entity_id,period));
CREATE TABLE recurring_expenses(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES properties(id),description TEXT NOT NULL,category TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),account_id TEXT NOT NULL REFERENCES financial_accounts(id),start_month TEXT NOT NULL,end_month TEXT,created_at TEXT NOT NULL);
CREATE INDEX lease_unit_dates ON leases(unit_id,start_date,end_date);
CREATE INDEX lease_tenant ON leases(tenant_id);
CREATE INDEX invoices_due ON invoices(due_date);
CREATE INDEX journal_scope_date ON journal_entries(property_id,tenant_id,entry_date);
CREATE INDEX journal_lines_account ON journal_lines(account_id,entry_id);
CREATE INDEX payments_lease_date ON payments(lease_id,payment_date);
CREATE INDEX allocations_invoice ON payment_allocations(invoice_id);
CREATE INDEX expenses_scope_date ON expenses(property_id,entry_date);
CREATE INDEX documents_scope ON documents(entity_type,entity_id);
CREATE INDEX audit_created ON activity_logs(created_at);

CREATE TABLE record_versions(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX record_versions_entity ON record_versions(entity_type,entity_id,created_at);

CREATE UNIQUE INDEX invoice_monthly_unique ON invoices(lease_id,month) WHERE kind IN ('rent');
CREATE UNIQUE INDEX invoice_latefee_unique ON invoices(lease_id,month) WHERE kind IN ('late_fee');
